function db(){static $p=null;if($p)return $p;$p=new PDO('mysql:host='.(getenv('DB_HOST')?:'127.0.0.1').';port='.(getenv('DB_PORT')?:'3306').';dbname='.(getenv('DB_NAME')?:'datasell').';charset=utf8mb4',getenv('DB_USER')?:'root',getenv('DB_PASS')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);return $p;}
function esc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function money($v){return '₦'.number_format((float)$v,2);}
function ref($p='TX'){return $p.'-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(3)));}
function live_mode(){return getenv('PROVIDER_LIVE')==='1';}
function csrf(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
function verify_csrf(){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??''))throw new Exception('Your session expired. Refresh and try again.');}
function price_for($plan,$role){if($plan['category']==='electricity')return 0.0;if($role==='api')return (float)$plan['api_price'];if($role==='reseller')return (float)$plan['reseller_price'];return (float)$plan['retail_price'];}
function role_label($u){if(!$u)return 'Guest';if((int)$u['is_admin']===1)return 'Administrator';return ['customer'=>'Customer','reseller'=>'Reseller','api'=>'API User'][$u['account_type']]??'Customer';}
