 if($action==='purchase'){$u=me();$id=(int)($_POST['plan_id']??0);$cat=$_POST['category']??'';$recipient=trim($_POST['recipient']??'');$custom=(float)($_POST['custom_amount']??0);$s=db()->prepare('SELECT * FROM service_plans WHERE id=? AND active=1');$s->execute([$id]);$pl=$s->fetch();if(!$pl||$pl['category']!==$cat)throw new Exception('Selected product is unavailable.');$role=$u['account_type']??'customer';$amount=$cat==='electricity'?$custom:price_for($pl,$role);if($amount<=0)throw new Exception('Enter a valid amount.');$details=json_encode(['provider'=>$pl['provider'],'plan'=>$pl['name'],'plan_code'=>$pl['code'],'recipient'=>$recipient,'pricing_tier'=>$role,'cost_price'=>(float)$pl['cost_price'],'selling_price'=>$amount,'mode'=>live_mode()?'live':'staging']);if(live_mode()){if($amount>$u['wallet_balance'])throw new Exception('Insufficient wallet balance.');$p=db();$p->beginTransaction();$q=$p->prepare('UPDATE users SET wallet_balance=wallet_balance-? WHERE id=? AND wallet_balance>=?');$q->execute([$amount,$u['id'],$amount]);if($q->rowCount()!==1){$p->rollBack();throw new Exception('Insufficient wallet balance.');}$p->prepare('INSERT INTO transactions(user_id,type,amount,status,reference,details) VALUES(?,?,?,?,?,?)')->execute([$u['id'],$cat,$amount,'pending',ref(),$details]);$p->commit();$msg='Order queued for provider processing.';}else{db()->prepare('INSERT INTO transactions(user_id,type,amount,status,reference,details) VALUES(?,?,?,?,?,?)')->execute([$u['id'],$cat,$amount,'pending',ref('DEMO'),$details]);$msg='Staging order created at your '.role_label($u).' price without debiting your wallet.';}}
 if($action==='approve'&&me()['is_admin']){$id=(int)$_POST['id'];$p=db();$p->beginTransaction();$s=$p->prepare("SELECT * FROM funding_requests WHERE id=? AND status='pending' FOR UPDATE");$s->execute([$id]);$r=$s->fetch();if(!$r)throw new Exception('Funding request not found.');$p->prepare("UPDATE funding_requests SET status='approved' WHERE id=?")->execute([$id]);$p->prepare('UPDATE users SET wallet_balance=wallet_balance+? WHERE id=?')->execute([$r['amount'],$r['user_id']]);$p->prepare('INSERT INTO transactions(user_id,type,amount,status,reference,details) VALUES(?,?,?,?,?,?)')->execute([$r['user_id'],'wallet_funding',$r['amount'],'successful',$r['reference'],json_encode(['source'=>'admin'])]);$p->commit();$msg='Wallet funded successfully.';}
